/**
 * QuickBooks Online Node - Version 1
 * Discriminator: resource=customer, operation=update
 */


interface Credentials {
  quickBooksOAuth2Api: CredentialReference;
}

export type QuickbooksV1CustomerUpdateParams = {
  resource: 'customer';
  operation: 'update';
/**
 * The ID of the customer to update
 */
    customerId: string | Expression<string>;
/**
 * Update Fields
 * @default {}
 */
    updateFields?: {
    /** Whether the customer is currently enabled for use by QuickBooks
     * @default true
     */
    Active?: boolean | Expression<boolean>;
    /** Open balance amount or amount unpaid by the customer
     */
    Balance?: string | Expression<string>;
    /** Cumulative open balance amount for the customer (or job) and all its sub-jobs
     * @default 0
     */
    BalanceWithJobs?: number | Expression<number>;
    /** Billing Address
     * @default {}
     */
    BillAddr?: {
        /** Details
     */
    details?: {
      /** City
       */
      City?: string | Expression<string>;
      /** Line 1
       */
      Line1?: string | Expression<string>;
      /** Postal Code
       */
      PostalCode?: string | Expression<string>;
      /** Latitude
       */
      Lat?: string | Expression<string>;
      /** Longitude
       */
      Long?: string | Expression<string>;
      /** Country Subdivision Code
       */
      CountrySubDivisionCode?: string | Expression<string>;
    };
  };
    /** Whether to bill this customer together with its parent
     * @default false
     */
    BillWithParent?: boolean | Expression<boolean>;
    /** Company Name
     */
    CompanyName?: string | Expression<string>;
    /** Family Name
     */
    FamilyName?: string | Expression<string>;
    /** Fully Qualified Name
     */
    FullyQualifiedName?: string | Expression<string>;
    /** Given Name
     */
    GivenName?: string | Expression<string>;
    /** Preferred Delivery Method
     * @default Print
     */
    PreferredDeliveryMethod?: 'Print' | 'Email' | 'None' | Expression<string>;
    /** Primary Email Address
     */
    PrimaryEmailAddr?: string | Expression<string>;
    /** Primary Phone
     */
    PrimaryPhone?: string | Expression<string>;
    /** Name of the customer as printed on a check
     */
    PrintOnCheckName?: string | Expression<string>;
    /** Whether transactions for this customer are taxable
     * @default false
     */
    Taxable?: boolean | Expression<boolean>;
  };
};

export type QuickbooksV1CustomerUpdateNode = {
  type: 'n8n-nodes-base.quickbooks';
  version: 1;
  config: NodeConfig<QuickbooksV1CustomerUpdateParams> & { credentials?: Credentials };
};